import React, {
  forwardRef,
  PropsWithChildren,
  ReactElement,
  useImperativeHandle,
  useRef,
} from 'react';

import { MultiMeterBarChartLegend } from './components/MultiMeterBarChartLegend.js';
import { MultiMeterBarChartOverlay } from './components/MultiMeterBarChartOverlay/MultiMeterBarChartOverlay.js';
import { MultiMeterBarChartPlot } from './components/MultiMeterBarChartPlot/MultiMeterBarChartPlot.js';
import { MultiMeterBarSegments } from './components/MultiMeterBarSegments.js';
import { MultiMeterBarChartTooltipProvider } from './context/MultiMeterBarChartTooltipContext.js';
import { useMultiMeterBarChartConfig } from './hooks/useMultiMeterBarChartConfig.js';
import { StoreProvider } from './providers/StoreProvider.js';
import { Icon } from './slots/Icon.js';
import { Label } from './slots/Label.js';
import { Legend } from './slots/Legend.js';
import { Max } from './slots/Max.js';
import { Min } from './slots/Min.js';
import { Segment } from './slots/Segment.js';
import { Tooltip } from './slots/Tooltip.js';
import { Value } from './slots/Value.js';
import type { MultiMeterBarChartConsumerConfig } from './types/multi-meter-bar-chart-config.js';
import {
  MultiMeterBarChartRef,
  MultiMeterBarChartProps,
} from './types/multi-meter-bar-chart.js';
import { useMergeRefs } from '../../../core/hooks/useMergeRefs.js';
import { useObserveContainerSize } from '../../core/components/chart-layout/hooks/useObserveContainerSize.js';
import { ChartType } from '../../core/types/chart-types.js';
import { MeterBarChartFormattedValue } from '../shared/components/formatted-value/MeterBarChartFormattedValue.js';
import { MeterBarLayout } from '../shared/components/meter-bar-layout/MeterBarLayout.js';
import { FormatterContext } from '../shared/context/FormatterContext.js';
import { getLabelValue } from '../shared/functions/get-label-value.js';
import {
  SIZE_DEFAULT,
  MIN_DEFAULT_VALUE,
  MAX_DEFAULT_VALUE,
} from '../shared/types/default.js';

/**
 * Multi meter bar chart component
 */
const _MultiMeterBarChart = forwardRef<
  HTMLDivElement,
  PropsWithChildren<MultiMeterBarChartProps>
>((props, forwardedRef) => {
  const { className, style } = props;

  const config = useMultiMeterBarChartConfig(props);

  const {
    colorPalette,
    size = SIZE_DEFAULT,
    min = MIN_DEFAULT_VALUE,
    max = MAX_DEFAULT_VALUE,
    formatter,
    iconSlot,
    labelSlot,
    valueSlot,
    minSlot,
    maxSlot,
    segments,
    legend,
    tooltip,
    totalValue,
  } = config;

  const multiMeterBarChartRef = useRef<MultiMeterBarChartRef>(null);

  useImperativeHandle(forwardedRef, () => {
    if (multiMeterBarChartRef.current) {
      const consumerConfig: MultiMeterBarChartConsumerConfig = {
        colorPalette,
        size,
        min,
        max,
        formatter,
        tooltip,
        legend,
      };
      multiMeterBarChartRef.current.getConfig = () =>
        JSON.stringify({ type: ChartType.MultiMeterBar, ...consumerConfig });
    }
    // We are ignoring this eslint rule as this will always be defined since we are relying on the consumer to pass the reference value.
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion,newline-before-return
    return multiMeterBarChartRef.current!;
  });
  const label = labelSlot ? getLabelValue(labelSlot as ReactElement) : '';

  const [{ width, wrapperHeight }, containerRef] = useObserveContainerSize();
  const ref = useMergeRefs([forwardedRef, containerRef, multiMeterBarChartRef]);

  return (
    <FormatterContext.Provider value={{ formatter }}>
      <StoreProvider colorPalette={colorPalette} segmentsSlot={segments}>
        <MeterBarLayout
          ref={ref}
          size={size}
          className={className}
          style={style}
        >
          {iconSlot && <MeterBarLayout.Icon>{iconSlot}</MeterBarLayout.Icon>}
          {labelSlot && (
            <MeterBarLayout.Label>{labelSlot}</MeterBarLayout.Label>
          )}
          {valueSlot && (
            <MeterBarLayout.Value>
              <MeterBarChartFormattedValue
                value={totalValue}
                total={max - min}
                auto={valueSlot?.auto}
              >
                {valueSlot?.value}
              </MeterBarChartFormattedValue>
            </MeterBarLayout.Value>
          )}
          <MeterBarLayout.Chart>
            <MultiMeterBarChartTooltipProvider
              data={{ tooltipConfig: tooltip, label }}
            >
              <MultiMeterBarChartOverlay>
                <MultiMeterBarChartPlot>
                  <MultiMeterBarSegments max={max} min={min} width={width} />
                </MultiMeterBarChartPlot>
              </MultiMeterBarChartOverlay>
            </MultiMeterBarChartTooltipProvider>
          </MeterBarLayout.Chart>
          {minSlot && (
            <MeterBarLayout.Min>
              <MeterBarChartFormattedValue value={min} auto={minSlot?.auto}>
                {minSlot?.value}
              </MeterBarChartFormattedValue>
            </MeterBarLayout.Min>
          )}
          {maxSlot && (
            <MeterBarLayout.Max>
              <MeterBarChartFormattedValue value={max} auto={maxSlot?.auto}>
                {maxSlot?.value}
              </MeterBarChartFormattedValue>
            </MeterBarLayout.Max>
          )}
          {legend && (
            <MeterBarLayout.Legend>
              <MultiMeterBarChartLegend height={wrapperHeight} width={width} />
            </MeterBarLayout.Legend>
          )}
        </MeterBarLayout>
      </StoreProvider>
    </FormatterContext.Provider>
  );
});

_MultiMeterBarChart['displayName'] = 'MultiMeterBarChart';

/**
 * The `MultiMeterBarChart` is a more complex version of the single meter bar,
 * it allows for different data inputs to be considered when presenting progress
 * toward a goal, consumption of a total, etc.
 */
export const MultiMeterBarChart = Object.assign(_MultiMeterBarChart, {
  Icon,
  Label,
  Legend,
  Max,
  Min,
  Segment,
  Value,
  Tooltip,
});
